import type { CatalogSource, Product } from "./types";

export class CatalogCache {
  private readonly pending = new Map<string, Promise<Product>>();

  constructor(private readonly source: CatalogSource) {}

  async get(tenant: string, sku: string): Promise<Product> {
    const key = `${tenant}:${sku}`;
    let request = this.pending.get(key);
    if (!request) {
      request = this.source.load(tenant, sku);
      this.pending.set(key, request);
      const current = request;
      void current.catch(() => {
        if (this.pending.get(key) === current) this.pending.delete(key);
      });
    }
    return { ...await request };
  }
}

